import{_ as u,a0 as p,w as e,s as l,ao as a,I as i,x as n,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"将手机作为你的 Linux 桌面的摄像头和麦克风 | LCTT x X-CMD","titleTemplate":false,"description":"将手机作为你的 Linux 桌面的摄像头和麦克风 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将手机作为你的 Linux 桌面的摄像头和麦克风 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将手机作为你的 Linux 桌面的摄像头和麦克风 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230828 Using Your Phone as Camera and Mic in Ubuntu Linux","title":"将手机作为你的 Linux 桌面的摄像头和麦克风","tag":"202309","desc":""},"relativePath":"202309/20230828 Using Your Phone as Camera and Mic in Ubuntu Linux.md","filePath":"[post].md"}'),d={name:"202309/20230828 Using Your Phone as Camera and Mic in Ubuntu Linux.md"};function b(m,t,g,f,h,k){const s=p("Link");return e(),l("div",null,[t[33]||(t[33]=a('<h1 id="将手机作为你的-linux-桌面的摄像头和麦克风" tabindex="-1">将手机作为你的 Linux 桌面的摄像头和麦克风 <a class="header-anchor" href="#将手机作为你的-linux-桌面的摄像头和麦克风" aria-label="Permalink to “将手机作为你的 Linux 桌面的摄像头和麦克风”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/07/155221kxjpb8j8j998xj50.jpg" alt=""></p><blockquote><p>当你的桌面系统缺乏网络摄像头和专用麦克风时，你可以考虑使用智能手机。这里将教你如何在 Ubuntu Linux 中完成这个设置。</p></blockquote><p>我和许多 Linux 用户一样，使用的是台式机。相较于笔记本电脑，并没有预装摄像头和麦克风。</p><p>若要获得与现代智能手机相媲美的画质，你可能需要购买一款高端的网络摄像头。</p><p>在此教程中，我将逐步指导你如何将你的手机用作麦克风和摄像头，这将非常适用于在线会议场景。</p><h3 id="ubuntu-下使用手机的摄像头和麦克风" tabindex="-1">Ubuntu 下使用手机的摄像头和麦克风 <a class="header-anchor" href="#ubuntu-下使用手机的摄像头和麦克风" aria-label="Permalink to “Ubuntu 下使用手机的摄像头和麦克风”">​</a></h3>',7)),i("blockquote",null,[i("p",null,[t[1]||(t[1]=n("🚧 本教程采用第三方网站 ",-1)),o(s,{href:"https://vdo.ninja/"},{default:r(()=>[...t[0]||(t[0]=[n("https://vdo.ninja/",-1)])]),_:1}),t[2]||(t[2]=n(" 来托管音频和视频，因此，这并不是一项完全的开源方案。",-1))])]),t[34]||(t[34]=a('<p>我将指引你完成以下步骤：</p><ul><li>安装 OBS （如果你还未安装）</li><li>通过 <code>vdo.ninja</code> 生成邀请链接</li><li>设置虚拟音频线缆（用于音频输出）</li><li>配置 OBS 以便从 <code>vdo.ninja</code> 重定向音视频流</li></ul><p>首先，我们来看第一步。</p><blockquote><p>📋 虽然本教程是在 Ubuntu 系统下完成的，但我相信，这些同样可以在其他 Linux 发行版上实现。你只需为你的发行版安装所需的包即可。你可以自行尝试，看看效果如何。</p></blockquote><h4 id="_1、在-ubuntu-中安装-obs" tabindex="-1">1、在 Ubuntu 中安装 OBS <a class="header-anchor" href="#_1、在-ubuntu-中安装-obs" aria-label="Permalink to “1、在 Ubuntu 中安装 OBS”">​</a></h4><p>OBS（Open Broadcaster Software）是众多用于录制和直播视频的优秀软件之一，许多直播者都选择使用 OBS 在各个数字化平台进行直播。</p><p>幸运的是，OBS 已经包含在 Ubuntu 的默认仓库中，你可以通过以下命令来安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install obs-studio</span></span></code></pre></div><h4 id="_2、通过-vdo-ninja-生成直播邀请" tabindex="-1">2、通过 VDO.ninja 生成直播邀请 <a class="header-anchor" href="#_2、通过-vdo-ninja-生成直播邀请" aria-label="Permalink to “2、通过 VDO.ninja 生成直播邀请”">​</a></h4><p>在这一节，我将教你如何在 vdo.ninja 上生成一个直播邀请，进而从你的手机上开始直播音频和视频。</p>',10)),i("p",null,[t[4]||(t[4]=n("首先，访问 ",-1)),o(s,{href:"https://vdo.ninja/"},{default:r(()=>[...t[3]||(t[3]=[n("VDO.ninja",-1)])]),_:1}),t[5]||(t[5]=n(" 并点击 “",-1)),t[6]||(t[6]=i("ruby",null,[n("创建可重用的邀请"),i("rt",null,"Create Reusable Invite")],-1)),t[7]||(t[7]=n("”：",-1))]),t[35]||(t[35]=a('<p><img src="https://itsfoss.com/content/images/2023/08/Click-on-create-reusable-Invite-button.png" alt=""></p><p>接下来你会看到很多选项，包括质量设置，添加视频效果等。我推荐你使用默认设置，因为高质量视频需要更快的处理速度和更多的带宽。</p><p>为了创建一个链接，你只需要点击 “<ruby>生成邀请链接<rt>GENERATE THE INVITE LINK</rt></ruby>” 按钮：</p><p><img src="https://itsfoss.com/content/images/2023/08/Click-on-the-generate-invite-link-button.png" alt=""></p><p>完成后你会看到：</p><ul><li>你需要用你的手机扫描的二维码（当然，你也可以选择使用链接）。</li><li>OBS 的链接。</li></ul><p><strong>稍后我会在本教程中继续介绍 OBS 配置，所以请暂时别关闭这个窗口。</strong></p><p>首先，用你的手机扫描二维码，它会将你跳转到 VDO.ninja 的另一个页面，此时你需要：</p><ul><li>选择 “<ruby>共享你的相机<rt>Share your Camera</rt></ruby>” 选项。</li><li>在视频源中选择使用前置或后置摄像头（默认为前置）。</li><li>点击 “<ruby>开始<rt>Start</rt></ruby>” 按钮后，它将开始在 OBS 连接的页面上进行直播。</li></ul><p><img src="https://itsfoss.com/content/images/2023/08/setup-vdo.ninja-on-phone.png" alt=""></p><h4 id="_3、在-ubuntu-上为-obs-配置虚拟线缆" tabindex="-1">3、在 Ubuntu 上为 OBS 配置虚拟线缆 <a class="header-anchor" href="#_3、在-ubuntu-上为-obs-配置虚拟线缆" aria-label="Permalink to “3、在 Ubuntu 上为 OBS 配置虚拟线缆”">​</a></h4><blockquote><p>🚧 这种设置方法仅适用于 PulseAudio，并且在重启系统后虚拟线缆将被撤销。</p></blockquote><p>首先，我们来解释一下“<ruby>虚拟线缆<rt>virtual cable</rt></ruby>”的概念，以及为何我们需要它来将手机做为摄像头和麦克风使用。</p><p>虚拟线缆是一种用于将音频流从一个应用传输到另一个应用的软件。</p><p>然而遗憾的是，它只支持 Windows 和 macOS。</p><p>啥？！那我为什么还要介绍这个呢？</p><p>答案其实很简单。我找到了一种变通方法，你可以在<strong>当前的会话</strong>中获得与虚拟线缆类似的功能。</p><p>要设置虚拟线缆，首先需要使用以下命令加载 <code>module-null-sink</code> 模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pactl load-module module-null-sink sink_name=Source</span></span></code></pre></div><p>然后，执行下面的命令创建一个名为 <code>VirtualMic</code> 的虚拟音源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pactl load-module module-virtual-source source_name=VirtualMic master=Source.monitor</span></span></code></pre></div><p>这两个命令将返回一些数字，但无需对其过多关注。</p><p>接下来，前往系统“<ruby>设置<rt>Settings</rt></ruby>”，找到“<ruby>声音<rt>Sound</rt></ruby>”部分的设置：</p><p><img src="https://itsfoss.com/content/images/2023/08/Open-sound-settings.png" alt=""></p><p>然后进入 “<ruby>输入<rt>Input</rt></ruby>” 部分，在此你会找到选择输入设备的选项。</p><p>将 “VirtualMic” 设为输入设备：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-virtul-mic-as-an-audio-input-in-Linux-to-use-phone-s-camera-and-mic-.png" alt=""></p><p>这样就设置完了！</p><p>不过，如我之前所述，一旦你重启电脑，虚拟音频的设置就会被撤销，如果你打算经常使用手机作为摄像头和麦克风，这可能会造成一定的不便。</p>',29)),i("p",null,[t[9]||(t[9]=n("为了解决这个问题，你可以为这两个命令 ",-1)),o(s,{href:"https://linuxhandbook.com/linux-alias-command/"},{default:r(()=>[...t[8]||(t[8]=[n("创建别名",-1)])]),_:1}),t[10]||(t[10]=n("，例如，为命令创建别名：",-1)),t[11]||(t[11]=i("code",null,"vc1",-1)),t[12]||(t[12]=n(" 和 ",-1)),t[13]||(t[13]=i("code",null,"vc2",-1)),t[14]||(t[14]=n("。",-1))]),i("p",null,[t[16]||(t[16]=n("完成后，你就可以像这样 ",-1)),o(s,{href:"https://linuxhandbook.com/run-multiple-commands/"},{default:r(()=>[...t[15]||(t[15]=[n("一次执行两个命令",-1)])]),_:1}),t[17]||(t[17]=n("：",-1)),t[18]||(t[18]=i("code",null,"vc1 && vc2",-1)),t[19]||(t[19]=n("。",-1))]),t[36]||(t[36]=a('<h4 id="_4、配置-obs-从手机直播音视频" tabindex="-1">4、配置 OBS 从手机直播音视频 <a class="header-anchor" href="#_4、配置-obs-从手机直播音视频" aria-label="Permalink to “4、配置 OBS 从手机直播音视频”">​</a></h4><p>开始阶段，你需要打开我之前告诉你不要关闭的 VDO.ninja 标签页，并复制 OBS 链接：</p><p><img src="https://itsfoss.com/content/images/2023/08/Copy-link-for-OBS.png" alt=""></p><p>然后启动 OBS，在 “<ruby>源<rt>Sources</rt></ruby>” 区域你会看到一个 “➕（加号）”按钮，点击这个按钮并选择 “<ruby>浏览<rt>Browser</rt></ruby>”。</p><p>接着会弹出一个对话框，让你创建或选择一个源，你只需按下 “OK” 按钮即可：</p><p><img src="https://itsfoss.com/content/images/2023/08/Create-new-source-for-streaming-in-OBS-to-use-camera-and-mic-of-your-phone-in-Ubuntu-1.png" alt=""></p><p>最后，将已经复制的链接粘贴进 “URL” 字段：</p><p><img src="https://itsfoss.com/content/images/2023/08/Paste-VDO.ninja-link-in-OBS-to-use-your-phone-s-camera-and-mic-in-Ubuntu-Linux.png" alt=""></p><p>然后你将能看到 OBS 正在使用你手机的摄像头：</p><p><img src="https://itsfoss.com/content/images/2023/08/Stream-audio-and-video-from-your-phone-to-Ubuntu-Linux-using-OBS.png" alt=""></p><p>不过为了从你的手机接收音频，还有一些额外步骤需要执行。</p><p>首先，在菜单中点击 “<ruby>文件<rt>File</rt></ruby>” 并选择 “<ruby>设置<rt>Settings</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Open-settings-in-OBS.png" alt=""></p><p>在出现的设置选项中选择 “<ruby>音频<rt>Audio</rt></ruby>”，然后寻找到 “<ruby>高级<rt>Advanced</rt></ruby>” 区域。</p><p>在 “高级” 区域里，你能找到 “<ruby>监控设备<rt>Monitoring Device</rt></ruby>” 的选项，这里你需要选择 “Source Audio/Sink sink”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-virtual-audio-in-OBS-to-use-phone-s-mic-in-ubuntu-Linux.png" alt=""></p><p>点击 “<ruby>应用<rt>Apply</rt></ruby>” 保存更改。</p><p>对于大部分用户，此时音频应该已经能够正常工作了。如果你的音频依然无法工作，那么你可以按照以下步骤操作。</p><p>在 “<ruby>音频混音器<rt>Audio Mixer</rt></ruby>” 区域，可能显示的是 “<ruby>浏览<rt>Browser</rt></ruby>” 或 “<ruby>桌面音频<rt>Desktop Audio</rt></ruby>”，也可能两者都显示。</p><p>点击 “桌面音频” 或 “浏览” 旁边的三个点（在我这个例子中，是 “桌面音频”），并选择 “<ruby>高级音频属性<rt>Advanced Audio Properties</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-advanced-option-to-use-audio-from-phone-in-Ubuntu-linux-using-OBS.png" alt=""></p><p>然后，对于 “浏览” 和 “桌面音频”，都选择 “<ruby>监控和输出<rt>Monitor and Output</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Enable-monitor-and-output-for-OBS.png" alt=""></p><p>这样就可以了！现在你可以从你的手机上享受摄像头和麦克风的功能了。</p><h4 id="_5、测试所有设置" tabindex="-1">5、测试所有设置 <a class="header-anchor" href="#_5、测试所有设置" aria-label="Permalink to “5、测试所有设置”">​</a></h4><p>为了测试这个设置，我在我们读书俱乐部的周会上用我的手机做为摄像头和麦克风，效果极佳。</p><p><img src="https://itsfoss.com/content/images/2023/08/Using-phone-s-camera-and-mic-in-Ubuntu-Linux.png" alt=""></p><p>你可以看到，上图显示摄像头和麦克风都在正常工作，这真的让我笑容满面 😸。</p><p>视频质量会取决于你的网络带宽，所以在开始重要的会议前，确保你有稳定的网络连接。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>作为一个没有摄像头和麦克风的台式计算机用户，我必须依靠笔记本或手机来参加工作会议，这让我感到非常烦躁。</p><p>需要注意的是，每次重启机器后，你都需要重新配置虚拟线缆，但这并不费时，因为只需要执行两条命令即可。</p><p>我已经多次使用这种解决方案，每一次都顺利运行。我真的希望你也能得到同样的结果。</p><p><em>（题图：MJ/223b56b7-ffcc-4311-bfa6-8a25bfd5ad11）</em></p><hr>',35)),i("p",null,[t[21]||(t[21]=n("via: ",-1)),o(s,{href:"https://itsfoss.com/ubuntu-phone-camera-mic/"},{default:r(()=>[...t[20]||(t[20]=[n("https://itsfoss.com/ubuntu-phone-camera-mic/",-1)])]),_:1})]),i("p",null,[t[25]||(t[25]=n("作者：",-1)),o(s,{href:"https://itsfoss.com/author/sagar/"},{default:r(()=>[...t[22]||(t[22]=[n("Sagar Sharma",-1)])]),_:1}),t[26]||(t[26]=n(" 选题：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[23]||(t[23]=[n("lujun9972",-1)])]),_:1}),t[27]||(t[27]=n(" 译者：ChatGPT 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[24]||(t[24]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[30]||(t[30]=n("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[28]||(t[28]=[n("LCTT",-1)])]),_:1}),t[31]||(t[31]=n(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:r(()=>[...t[29]||(t[29]=[n("Linux中国",-1)])]),_:1}),t[32]||(t[32]=n(" 荣誉推出",-1))])])}const T=u(d,[["render",b]]);export{x as __pageData,T as default};
